/// 🔤️ An authored face the framework embeds — Anta for [`TextFace::Sans`] (React's `--font-sans`, the ui atlas's default
/// face), Share Tech Mono for [`TextFace::Mono`]; both the Latin subsets under `🖼️assets/🔤️fonts`.
#[derive(Clone, Copy, Debug, Default, Hash, PartialEq, Eq)]
pub enum TextFace {
    #[default]
    Sans,
    Mono,
}

static ANTA_LATIN: &[u8] = include_bytes!("../🖼️assets/🔤️fonts/🚀️anta/🏛️latin/📖️regular/🔤️outline.ttf");
static SHARE_TECH_MONO_LATIN: &[u8] = include_bytes!("../🖼️assets/🔤️fonts/⌨️share-tech-mono/🏛️latin/📖️regular/🔤️outline.ttf");

impl TextFace {
    /// 📦️ The embedded font file of this face.
    pub fn bytes(self) -> &'static [u8] {
        match self {
            TextFace::Sans => ANTA_LATIN,
            TextFace::Mono => SHARE_TECH_MONO_LATIN,
        }
    }

    /// 🔠️ This face parsed once per process.
    pub fn font(self) -> Result<&'static FontFile<'static>, FontError> {
        static SANS: OnceLock<Result<FontFile<'static>, FontError>> = OnceLock::new();
        static MONO: OnceLock<Result<FontFile<'static>, FontError>> = OnceLock::new();
        let cell = match self {
            TextFace::Sans => &SANS,
            TextFace::Mono => &MONO,
        };
        cell.get_or_init(|| FontFile::parse(self.bytes())).as_ref().map_err(Clone::clone)
    }
}
