use super::*;
use swash::shape::ShapeContext;

/// 🧫️ The Chromium-measured advance corpus the ui stack's WG11 T7a/T7b laws pin (`🖱️ui/🧫️fixtures/🔤️text-advances`).
fn corpus() -> serde_json::Value {
    serde_json::from_str(include_str!("../../../🖱️ui/🧫️fixtures/🔤️text-advances/🔣️.json")).expect("the text advance corpus parses")
}

fn corpus_face(row: &serde_json::Value) -> TextFace {
    match row["face"].as_str() {
        Some("mono") => TextFace::Mono,
        _ => TextFace::Sans,
    }
}

fn oracle_font(face: TextFace) -> swash::FontRef<'static> {
    swash::FontRef::from_index(face.bytes(), 0).expect("swash reads the embedded face")
}

/// 🔮️ swash's advance per em — the exact reading of the ui stack's `font_advance_em` for a scalar of the authored face.
fn oracle_advance_em(font: swash::FontRef<'static>, ch: char) -> Option<f32> {
    let glyph = font.charmap().map(ch);
    let units = f32::from(font.metrics(&[]).units_per_em);
    (glyph != 0).then(|| font.glyph_metrics(&[]).advance_width(glyph) / units)
}

/// 🔮️ swash's pair kerning per em — the exact reading of the ui stack's `PairKerning::em`: the pair shaped alone with
/// ligatures and contextual alternates off, less its two nominal advances.
fn oracle_kerning_em(shaper: &mut ShapeContext, font: swash::FontRef<'static>, left: char, right: char) -> f32 {
    if is_default_ignorable(left) || is_default_ignorable(right) {
        return 0.0;
    }
    let (charmap, metrics) = (font.charmap(), font.glyph_metrics(&[]));
    let units = f32::from(font.metrics(&[]).units_per_em);
    if charmap.map(left) == 0 || charmap.map(right) == 0 {
        return 0.0;
    }
    let pair: String = [left, right].into_iter().collect();
    let mut shaping = shaper.builder(font).features(&[("liga", 0), ("clig", 0), ("calt", 0)]).build();
    shaping.add_str(&pair);
    let (mut shaped, mut nominal, mut glyphs) = (0.0f32, 0.0f32, 0usize);
    shaping.shape_with(|cluster| {
        for glyph in cluster.glyphs {
            shaped += glyph.advance;
            nominal += metrics.advance_width(glyph.id);
            glyphs += 1;
        }
    });
    if glyphs == 2 {
        (shaped - nominal) / units
    } else {
        0.0
    }
}

fn polygon_area_and_bounds(contours: &[Vec<(f64, f64)>]) -> (f64, [f64; 4]) {
    let mut area = 0.0;
    let mut bounds = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
    for contour in contours {
        for (index, (x, y)) in contour.iter().enumerate() {
            let (nx, ny) = contour[(index + 1) % contour.len()];
            area += x * ny - nx * y;
            bounds = [bounds[0].min(*x), bounds[1].min(*y), bounds[2].max(*x), bounds[3].max(*y)];
        }
    }
    (area / 2.0, bounds)
}

const FLATTEN_STEPS: usize = 16;

fn quad_points(from: (f64, f64), control: (f64, f64), to: (f64, f64)) -> impl Iterator<Item = (f64, f64)> {
    (1..=FLATTEN_STEPS).map(move |step| {
        let t = step as f64 / FLATTEN_STEPS as f64;
        let u = 1.0 - t;
        (u * u * from.0 + 2.0 * u * t * control.0 + t * t * to.0, u * u * from.1 + 2.0 * u * t * control.1 + t * t * to.1)
    })
}

fn flattened_reader_outline(path: &BezPath) -> Vec<Vec<(f64, f64)>> {
    let mut contours: Vec<Vec<(f64, f64)>> = Vec::new();
    let mut pen = (0.0, 0.0);
    for element in path.elements() {
        match element {
            semio_framework_geometry::PathEl::MoveTo(p) => {
                pen = (p.x, p.y);
                contours.push(vec![pen]);
            }
            semio_framework_geometry::PathEl::LineTo(p) => {
                pen = (p.x, p.y);
                contours.last_mut().expect("contour").push(pen);
            }
            semio_framework_geometry::PathEl::QuadTo(c, p) => {
                contours.last_mut().expect("contour").extend(quad_points(pen, (c.x, c.y), (p.x, p.y)));
                pen = (p.x, p.y);
            }
            semio_framework_geometry::PathEl::CurveTo(..) => panic!("TrueType outlines carry no cubic segments"),
            semio_framework_geometry::PathEl::ClosePath => {}
        }
    }
    contours
}

fn flattened_oracle_outline(outline: &swash::scale::outline::Outline) -> Vec<Vec<(f64, f64)>> {
    let points: Vec<(f64, f64)> = outline.points().iter().map(|p| (f64::from(p.x), f64::from(p.y))).collect();
    let mut contours: Vec<Vec<(f64, f64)>> = Vec::new();
    let (mut at, mut pen) = (0usize, (0.0, 0.0));
    for verb in outline.verbs() {
        match verb {
            swash::zeno::Verb::MoveTo => {
                pen = points[at];
                at += 1;
                contours.push(vec![pen]);
            }
            swash::zeno::Verb::LineTo => {
                pen = points[at];
                at += 1;
                contours.last_mut().expect("contour").push(pen);
            }
            swash::zeno::Verb::QuadTo => {
                contours.last_mut().expect("contour").extend(quad_points(pen, points[at], points[at + 1]));
                pen = points[at + 1];
                at += 2;
            }
            swash::zeno::Verb::CurveTo => panic!("TrueType outlines carry no cubic segments"),
            swash::zeno::Verb::Close => {}
        }
    }
    contours
}

