/// 🤝️ LAW: every pair of mapped printable Latin-1 scalars kerns by exactly swash's shaped pair adjustment — the ui stack's
/// `PairKerning::em` reading — so an exported label kerns like both shells.
#[test]
fn every_latin_pair_kerns_as_swash_shapes_it() {
    let mut shaper = ShapeContext::new();
    for face in [TextFace::Sans, TextFace::Mono] {
        let (font, oracle) = (face.font().expect("face"), oracle_font(face));
        let scalars: Vec<char> = (0x20u32..=0xFF).filter_map(char::from_u32).filter(|ch| font.glyph_index(*ch).is_some()).collect();
        let mut kerned = 0usize;
        for left in &scalars {
            for right in &scalars {
                let expected = oracle_kerning_em(&mut shaper, oracle, *left, *right);
                let measured = font.pair_kerning_em(*left, *right);
                assert!((measured - expected).abs() < 1e-6, "{face:?} {left:?}+{right:?}: reader {measured} vs swash {expected}");
                kerned += usize::from(expected != 0.0);
            }
        }
        match face {
            TextFace::Sans => assert!(kerned > 100, "Anta kerns {kerned} Latin-1 pairs"),
