/// 🔤️ LAW (the WG11 T7a/T7b corpus): every row's advances and pair kerning equal swash's reading scalar by scalar and pair by
/// pair, and sum to Chromium's unkerned and kerned DOM widths within the corpus tolerance.
#[test]
fn the_shared_corpus_measures_as_the_ui_stack_and_chromium_do() {
    let fixture = corpus();
    let tolerance = fixture["tolerancePx"].as_f64().expect("tolerance") as f32;
    let mut shaper = ShapeContext::new();
    for row in fixture["rows"].as_array().expect("rows") {
        let face = corpus_face(row);
        let (font, oracle) = (face.font().expect("face"), oracle_font(face));
        let text = row["text"].as_str().expect("text");
        let size = row["sizePx"].as_f64().expect("size") as f32;
        let chars: Vec<char> = text.chars().collect();
