            kerning += em * size;
        }
        let unkerned = row["unkernedWidthPx"].as_f64().expect("unkerned") as f32;
        let kerned = row["kernedWidthPx"].as_f64().expect("kerned") as f32;
        assert!((advances - unkerned).abs() <= tolerance, "{face:?} {size}px {text:?}: {advances} vs Chromium {unkerned}");
        assert!((advances + kerning - kerned).abs() <= tolerance, "{face:?} {size}px {text:?}: {} vs Chromium {kerned}", advances + kerning);
        let run = font.text_run(text, f64::from(size)).expect("run");
        assert!((run.advance as f32 - (advances + kerning)).abs() < 1e-3, "{text:?}: run advance {} vs {}", run.advance, advances + kerning);
    }
}

/// 🤝️ The two pairs the ui law pins at Chromium's own kerning (−0.0928 em and −0.0391 em).
#[test]
fn anta_kerns_the_pinned_pairs_at_chromiums_values() {
    let font = TextFace::Sans.font().expect("face");
    for (left, right, chromium) in [('A', 'V', -0.0928f32), ('f', 'o', -0.0391)] {
        let em = font.pair_kerning_em(left, right);
        assert!((em - chromium).abs() < 0.0005, "{left:?}+{right:?}: {em}");
    }
    assert_eq!(font.pair_kerning_em('o', '\u{200b}'), 0.0, "a default-ignorable scalar never kerns");
    assert_eq!(font.pair_kerning_em('o', '🔥'), 0.0, "a scalar outside the face never kerns");
}

/// ✒️ LAW: every glyph of both faces outlines exactly as swash's own unhinted scaler reads it (same enclosed signed area
/// and the same bounds, both flattened alike).
#[test]
fn every_glyph_outlines_as_swashs_scaler_reads_it() {
    let mut context = swash::scale::ScaleContext::new();
    for face in [TextFace::Sans, TextFace::Mono] {
        let (font, oracle) = (face.font().expect("face"), oracle_font(face));
        let mut scaler = context.builder(oracle).size(f32::from(font.units_per_em())).hint(false).build();
        let mut outlined = 0usize;
        for glyph in 0..font.glyph_count() {
            let ours = flattened_reader_outline(&font.glyph_outline(GlyphId(glyph)).expect("outline"));
            let theirs = scaler.scale_outline(glyph).map(|outline| flattened_oracle_outline(&outline)).unwrap_or_default();
            let theirs: Vec<Vec<(f64, f64)>> = theirs.into_iter().filter(|contour| contour.len() > 1).collect();
            assert_eq!(ours.len(), theirs.len(), "{face:?} glyph {glyph} contour count");
            if ours.is_empty() {
                continue;
            }
            let ((area, bounds), (oracle_area, oracle_bounds)) = (polygon_area_and_bounds(&ours), polygon_area_and_bounds(&theirs));
            assert!((area - oracle_area).abs() <= 1e-3 * oracle_area.abs().max(1.0), "{face:?} glyph {glyph} area {area} vs {oracle_area}");
            for (mine, oracle_edge) in bounds.iter().zip(oracle_bounds) {
                assert!((mine - oracle_edge).abs() < 1e-3, "{face:?} glyph {glyph} bounds {bounds:?} vs {oracle_bounds:?}");
            }
            outlined += 1;
        }
        assert!(outlined > 90, "{face:?} outlined {outlined} glyphs");
    }
}

#[test]
fn a_text_run_places_kerned_glyphs_on_a_y_down_baseline() {
    let font = TextFace::Sans.font().expect("face");
    let run = font.text_run("AV", 100.0).expect("run");
    let (a, v) = (font.glyph_index('A').expect("A"), font.glyph_index('V').expect("V"));
    let expected = (f64::from(font.advance_units(a)) + f64::from(font.advance_units(v)) + f64::from(font.pair_kerning_units(a, v))) * 100.0 / f64::from(font.units_per_em());
    assert!((run.advance - expected).abs() < 1e-9, "{} vs {expected}", run.advance);
    let bounds = run.outline.bounding_box();
    assert!(bounds.y0() < 0.0 && bounds.y1() <= 1.0, "capitals rise above the baseline in a y-down space: {bounds:?}");
    assert_eq!(font.text_run("\u{200b}", 16.0).expect("run").advance, 0.0, "a default-ignorable scalar advances by nothing");
    let tofu = font.text_run("\u{4e00}", 16.0).expect("run");
    assert_eq!(tofu.advance, f64::from(font.advance_units(GlyphId::NOTDEF)) * 16.0 / f64::from(font.units_per_em()), "an uncovered scalar advances as .notdef");
}

