//! 🧮️ The target-neutral CPU tier: a [`VectorScene`] rasterized into straight RGBA8 on any target (native hosts, every
//! `wasm32-wasip2` plugin guest, the browser renderer) in bounded, resumable steps.
//!
//! Painting model (SVG's, so an SVG renderer is a usable oracle): ops composite source-over in order into a premultiplied
//! RGBA8 canvas initialised with the background. A fill covers its path under its [`FillRule`] with every subpath
//! implicitly closed; coverage is exact signed-area accumulation per pixel on each scanline (no supersampling), so edges are
//! anti-aliased analytically. Curves are flattened in device space to within [`FLATTEN_TOLERANCE_PX`]. A stroke is expanded
//! in its path's own coordinate space into positively wound polygons — segment bodies, joins (miter within the limit, else
//! bevel; round; bevel) and caps on open subpaths (butt, round, square; a lone point draws a round or square dot) — then
//! filled under the non-zero rule. An image paint samples its texels bilinearly (premultiplied, edge-clamped) at pixel
//! centres. Rows are the unit of work: [`CpuRasterJob::step`] spends its fuel row by row across ops, so a caller can report
//! progress between steps and cancel by not stepping again (the job holds nothing but memory; dropping it releases all).
//!
//! Bounds: at most [`CPU_RASTER_MAX_EDGE`] pixels per edge and [`CPU_RASTER_MAX_PIXELS`] pixels in all; memory is the
//! canvas (4 bytes per pixel), one accumulation row, and the edge list of the op being painted.
//!
//! @see https://www.w3.org/TR/SVG11/painting.html
//! @see https://www.w3.org/TR/SVG2/painting.html#LineJoin

use super::{DrawOp, FillRule, ImagePaint, LineCap, LineJoin, Paint, StrokeStyle, VectorScene};
use semio_framework_geometry::{Affine, BezPath, PathEl, Point};
use semio_framework_pixels::RasterImage;

/// 📏️ Largest raster edge the CPU tier accepts, in pixels.
pub const CPU_RASTER_MAX_EDGE: u32 = 16_384;
/// 🧱️ Largest raster the CPU tier accepts, in pixels (64 MiB of canvas).
pub const CPU_RASTER_MAX_PIXELS: u64 = 16_777_216;
/// 〰️ Largest distance between a flattened curve and its chords, in device pixels.
pub const FLATTEN_TOLERANCE_PX: f64 = 0.1;
/// ✂️ Most chords one curve segment or round join is flattened into.
const MAX_SUBDIVISIONS: usize = 4096;

//#region 🔖️Job
/// 🚨️ Why a scene cannot be rasterized.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CpuRasterError {
    EmptySize { width: u32, height: u32 },
    TooLarge { width: u32, height: u32 },
    Incomplete,
}

impl std::fmt::Display for CpuRasterError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::EmptySize { width, height } => write!(formatter, "a {width}×{height} raster has no pixels"),
            Self::TooLarge { width, height } => write!(formatter, "a {width}×{height} raster exceeds the CPU tier's bound of {CPU_RASTER_MAX_EDGE} pixels per edge and {CPU_RASTER_MAX_PIXELS} pixels in all"),
            Self::Incomplete => formatter.write_str("the raster job was finished before its last step completed"),
        }
    }
}

impl std::error::Error for CpuRasterError {}

/// 📊️ Work done and work in all, in pixel-row units (each op row costs its clipped bounding-box width, each op one unit to
/// prepare); `completed == total` exactly when the job is complete.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RasterProgress {
    pub completed: u64,
    pub total: u64,
}

/// 🚦️ What one [`CpuRasterJob::step`] reports.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RasterStep {
    Pending(RasterProgress),
    Complete,
}

/// ⏯️ One scene being rasterized: owns the scene, the canvas and the state of the op in progress.
pub struct CpuRasterJob {
    ops: std::vec::IntoIter<DrawOp>,
    width: usize,
    height: usize,
    canvas: Vec<u8>,
    accumulation: Vec<f32>,
    current: Option<OpRaster>,
    progress: RasterProgress,
}

impl CpuRasterJob {
    /// 🏗️ A job painting `scene` over `background` (straight RGBA) into a `width` × `height` canvas.
    pub fn new(scene: VectorScene, width: u32, height: u32, background: [f32; 4]) -> Result<Self, CpuRasterError> {
        if width == 0 || height == 0 {
            return Err(CpuRasterError::EmptySize { width, height });
        }
        if width > CPU_RASTER_MAX_EDGE || height > CPU_RASTER_MAX_EDGE || u64::from(width) * u64::from(height) > CPU_RASTER_MAX_PIXELS {
            return Err(CpuRasterError::TooLarge { width, height });
        }
        let (columns, rows) = (width as usize, height as usize);
        let total = scene.ops.iter().map(|op| op_units(op, columns, rows)).sum();
        let fill = premultiplied_bytes(background);
        let mut canvas = Vec::with_capacity(columns * rows * 4);
        for _ in 0..columns * rows {
            canvas.extend_from_slice(&fill);
        }
        Ok(Self { ops: scene.ops.into_iter(), width: columns, height: rows, canvas, accumulation: vec![0.0; columns + 2], current: None, progress: RasterProgress { completed: 0, total } })
    }

    /// 📊️ The work done so far.
    pub fn progress(&self) -> RasterProgress {
        self.progress
    }

    /// ⏭️ Spends up to `fuel` units of work (at least one row or one op preparation per call) and reports whether the scene
    /// is fully painted.
    pub fn step(&mut self, fuel: u64) -> RasterStep {
        let mut spent = 0u64;
        loop {
            if self.current.is_none() {
                let Some(op) = self.ops.next() else {
                    self.progress.completed = self.progress.total;
                    return RasterStep::Complete;
                };
                self.current = Some(OpRaster::prepare(op, self.width, self.height));
                self.progress.completed += 1;
                spent += 1;
            }
            if let Some(op) = self.current.as_mut() {
                while op.row < op.row_end && spent < fuel.max(1) {
                    op.paint_row(&mut self.canvas, &mut self.accumulation, self.width);
                    self.progress.completed += op.units_per_row;
                    spent += op.units_per_row;
                }
                if op.row >= op.row_end {
                    self.current = None;
                }
            }
            if spent >= fuel.max(1) {
                return if self.current.is_none() && self.ops.len() == 0 {
                    self.progress.completed = self.progress.total;
                    RasterStep::Complete
                } else {
                    RasterStep::Pending(self.progress)
                };
            }
        }
    }

    /// 🏁️ The painted raster as straight RGBA8 — [`CpuRasterError::Incomplete`] before the last step completed.
    pub fn finish(self) -> Result<RasterImage, CpuRasterError> {
        if self.current.is_some() || self.ops.len() > 0 {
            return Err(CpuRasterError::Incomplete);
        }
        let mut pixels = self.canvas;
        for pixel in pixels.chunks_exact_mut(4) {
            let alpha = pixel[3];
            if alpha == 0 {
                pixel.copy_from_slice(&[0, 0, 0, 0]);
            } else if alpha < 255 {
                for channel in &mut pixel[..3] {
                    *channel = ((u32::from(*channel) * 255 + u32::from(alpha) / 2) / u32::from(alpha)).min(255) as u8;
                }
            }
        }
        Ok(RasterImage { width: self.width as u32, height: self.height as u32, pixels })
    }
}

/// 🖼️ Runs a whole [`CpuRasterJob`] in one call — for callers whose own bounded step already covers the scene's size.
pub fn rasterize(scene: VectorScene, width: u32, height: u32, background: [f32; 4]) -> Result<RasterImage, CpuRasterError> {
    let mut job = CpuRasterJob::new(scene, width, height, background)?;
    while job.step(u64::MAX) != RasterStep::Complete {}
    job.finish()
}
//#endregion 🔖️Job

//#region 🔖️Geometry
fn map(m: &[f64; 6], p: Point) -> Point {
    Point::new(m[0] * p.x + m[2] * p.y + m[4], m[1] * p.x + m[3] * p.y + m[5])
}

fn distance(a: Point, b: Point) -> f64 {
    (b.x - a.x).hypot(b.y - a.y)
}

fn subdivisions(second_difference: f64, factor: f64, tolerance: f64) -> usize {
    ((factor * second_difference / tolerance).sqrt().ceil() as usize).clamp(1, MAX_SUBDIVISIONS)
}

/// 〰️ `path` mapped through `m` and flattened to within `tolerance` as polylines `(points, closed)`, one per subpath.
fn flatten(path: &BezPath, m: &[f64; 6], tolerance: f64) -> Vec<(Vec<Point>, bool)> {
    let mut subpaths: Vec<(Vec<Point>, bool)> = Vec::new();
    let mut current: Vec<Point> = Vec::new();
    let (mut start, mut pen) = (Point::ZERO, Point::ZERO);
    let flush = |current: &mut Vec<Point>, subpaths: &mut Vec<(Vec<Point>, bool)>, closed: bool| {
        if !current.is_empty() {
            subpaths.push((std::mem::take(current), closed));
        }
    };
    for element in path.elements() {
        match element {
            PathEl::MoveTo(p) => {
                flush(&mut current, &mut subpaths, false);
                start = map(m, p);
                pen = start;
                current.push(pen);
            }
            PathEl::LineTo(p) => {
                if current.is_empty() {
                    current.push(pen);
                }
                pen = map(m, p);
                current.push(pen);
            }
            PathEl::QuadTo(c, p) => {
                if current.is_empty() {
                    current.push(pen);
                }
                let (p0, p1, p2) = (pen, map(m, c), map(m, p));
                let steps = subdivisions((p0.x - 2.0 * p1.x + p2.x).hypot(p0.y - 2.0 * p1.y + p2.y), 0.25, tolerance);
                for step in 1..=steps {
                    let t = step as f64 / steps as f64;
                    let u = 1.0 - t;
                    current.push(Point::new(u * u * p0.x + 2.0 * u * t * p1.x + t * t * p2.x, u * u * p0.y + 2.0 * u * t * p1.y + t * t * p2.y));
                }
                pen = p2;
            }
            PathEl::CurveTo(c1, c2, p) => {
                if current.is_empty() {
                    current.push(pen);
                }
                let (p0, p1, p2, p3) = (pen, map(m, c1), map(m, c2), map(m, p));
                let second = (p0.x - 2.0 * p1.x + p2.x).hypot(p0.y - 2.0 * p1.y + p2.y).max((p1.x - 2.0 * p2.x + p3.x).hypot(p1.y - 2.0 * p2.y + p3.y));
                let steps = subdivisions(second, 0.75, tolerance);
                for step in 1..=steps {
                    let t = step as f64 / steps as f64;
                    let u = 1.0 - t;
                    let (w0, w1, w2, w3) = (u * u * u, 3.0 * u * u * t, 3.0 * u * t * t, t * t * t);
                    current.push(Point::new(w0 * p0.x + w1 * p1.x + w2 * p2.x + w3 * p3.x, w0 * p0.y + w1 * p1.y + w2 * p2.y + w3 * p3.y));
                }
                pen = p3;
            }
            PathEl::ClosePath => {
                flush(&mut current, &mut subpaths, true);
                pen = start;
            }
        }
    }
    flush(&mut current, &mut subpaths, false);
    subpaths
}

fn positively_wound(mut polygon: Vec<Point>) -> Vec<Point> {
    let area: f64 = (0..polygon.len()).map(|i| {
        let (a, b) = (polygon[i], polygon[(i + 1) % polygon.len()]);
        a.x * b.y - b.x * a.y
    }).sum();
    if area < 0.0 {
        polygon.reverse();
    }
    polygon
}

/// ⭕️ Points on the arc of `radius` around `centre` from angle `from` sweeping `sweep` radians, flattened to within the
/// tolerance (`tolerance` in the arc's own units), both ends included.
fn arc_points(centre: Point, radius: f64, from: f64, sweep: f64, tolerance: f64) -> Vec<Point> {
    let step = if radius > tolerance { 2.0 * (1.0 - tolerance / radius).acos() } else { std::f64::consts::FRAC_PI_2 };
    let count = ((sweep.abs() / step.max(1e-6)).ceil() as usize).clamp(1, MAX_SUBDIVISIONS);
    (0..=count).map(|index| {
        let angle = from + sweep * index as f64 / count as f64;
        Point::new(centre.x + radius * angle.cos(), centre.y + radius * angle.sin())
    }).collect()
}

/// ✒️ The stroke outline of one flattened subpath as positively wound polygons, in the subpath's own coordinates;
/// `tolerance` is the flattening tolerance in those coordinates.
fn stroke_polygons(points: &[Point], closed: bool, style: &StrokeStyle, tolerance: f64) -> Vec<Vec<Point>> {
    let half = style.width / 2.0;
    let mut vertices: Vec<Point> = Vec::with_capacity(points.len());
    for p in points {
        if vertices.last().is_none_or(|last| distance(*last, *p) > 1e-9) {
            vertices.push(*p);
        }
    }
    if closed && vertices.len() > 2 && distance(vertices[0], *vertices.last().unwrap_or(&vertices[0])) <= 1e-9 {
        vertices.pop();
    }
    if vertices.len() == 1 {
        let v = vertices[0];
        return match style.cap {
            LineCap::Butt => Vec::new(),
            LineCap::Round => vec![positively_wound(arc_points(v, half, 0.0, std::f64::consts::TAU, tolerance))],
            LineCap::Square => vec![positively_wound(vec![Point::new(v.x - half, v.y - half), Point::new(v.x + half, v.y - half), Point::new(v.x + half, v.y + half), Point::new(v.x - half, v.y + half)])],
        };
    }
    if vertices.len() < 2 {
        return Vec::new();
    }
    let closed = closed && vertices.len() > 2;
    let count = vertices.len();
    let direction = |i: usize| {
        let (a, b) = (vertices[i % count], vertices[(i + 1) % count]);
        let length = distance(a, b);
        Point::new((b.x - a.x) / length, (b.y - a.y) / length)
    };
    let mut polygons = Vec::new();
    let segments = if closed { count } else { count - 1 };
    for i in 0..segments {
        let (a, b, d) = (vertices[i], vertices[(i + 1) % count], direction(i));
        let n = Point::new(-d.y * half, d.x * half);
        polygons.push(positively_wound(vec![Point::new(a.x + n.x, a.y + n.y), Point::new(b.x + n.x, b.y + n.y), Point::new(b.x - n.x, b.y - n.y), Point::new(a.x - n.x, a.y - n.y)]));
    }
    let joints: Vec<usize> = if closed { (0..count).collect() } else { (1..count - 1).collect() };
    for joint in joints {
        let incoming = direction((joint + count - 1) % count);
        let outgoing = direction(joint);
        let turn = incoming.x * outgoing.y - incoming.y * outgoing.x;
        if turn.abs() < 1e-12 && incoming.x * outgoing.x + incoming.y * outgoing.y > 0.0 {
            continue;
        }
        let side = if turn > 0.0 { -1.0 } else { 1.0 };
        let v = vertices[joint];
        let n_in = Point::new(-incoming.y * half * side, incoming.x * half * side);
        let n_out = Point::new(-outgoing.y * half * side, outgoing.x * half * side);
        let (a, b) = (Point::new(v.x + n_in.x, v.y + n_in.y), Point::new(v.x + n_out.x, v.y + n_out.y));
        let polygon = match style.join {
            LineJoin::Round => {
                let from = n_in.y.atan2(n_in.x);
                let mut sweep = n_out.y.atan2(n_out.x) - from;
                if sweep > std::f64::consts::PI {
                    sweep -= std::f64::consts::TAU;
                } else if sweep < -std::f64::consts::PI {
                    sweep += std::f64::consts::TAU;
                }
                let mut fan = vec![v];
                fan.extend(arc_points(v, half, from, sweep, tolerance));
                fan
            }
            LineJoin::Miter | LineJoin::Bevel => {
                let cos_phi = ((n_in.x * n_out.x + n_in.y * n_out.y) / (half * half)).clamp(-1.0, 1.0);
                let cos_half = ((1.0 + cos_phi) / 2.0).sqrt();
                if style.join == LineJoin::Miter && cos_half > 1e-12 && cos_half >= 1.0 / style.miter_limit.max(1.0) {
                    let bisector = Point::new(n_in.x + n_out.x, n_in.y + n_out.y);
                    let length = bisector.x.hypot(bisector.y);
                    let reach = half / cos_half;
                    vec![v, a, Point::new(v.x + bisector.x / length * reach, v.y + bisector.y / length * reach), b]
                } else {
                    vec![v, a, b]
                }
            }
        };
        polygons.push(positively_wound(polygon));
    }
    if !closed {
        for (end, d) in [(vertices[0], direction(0)), (vertices[count - 1], direction(count - 2))].into_iter().zip([-1.0, 1.0]).map(|((v, d), sign)| (v, Point::new(d.x * sign, d.y * sign))) {
            let n = Point::new(-d.y * half, d.x * half);
            match style.cap {
                LineCap::Butt => {}
                LineCap::Square => polygons.push(positively_wound(vec![
                    Point::new(end.x + n.x, end.y + n.y),
                    Point::new(end.x + n.x + d.x * half, end.y + n.y + d.y * half),
                    Point::new(end.x - n.x + d.x * half, end.y - n.y + d.y * half),
                    Point::new(end.x - n.x, end.y - n.y),
                ])),
                LineCap::Round => {
                    let from = n.y.atan2(n.x);
                    let sweep = if n.x * d.y - n.y * d.x > 0.0 { std::f64::consts::PI } else { -std::f64::consts::PI };
                    polygons.push(positively_wound(arc_points(end, half, from, sweep, tolerance)));
                }
            }
        }
    }
    polygons
}
