#[test]
fn stepping_reports_monotonic_progress_and_paints_what_one_call_paints() {
    let scene = || {
        let mut scene = VectorScene::new();
        scene.fill(rectangle(1.0, 1.0, 30.0, 20.0), IDENTITY, [0.9, 0.1, 0.1, 0.7]);
        scene.stroke(rectangle(4.0, 4.0, 24.0, 18.0), IDENTITY, [0.1, 0.2, 0.9, 1.0], 3.0);
        scene
    };
    let mut job = CpuRasterJob::new(scene(), 32, 24, [1.0, 1.0, 1.0, 1.0]).expect("job");
    let total = job.progress().total;
    let (mut last, mut steps) = (0, 0);
    while let RasterStep::Pending(progress) = job.step(7) {
        assert!(progress.completed > last && progress.completed < total, "{progress:?}");
        last = progress.completed;
        steps += 1;
    }
    assert_eq!(job.progress().completed, total);
    assert!(steps > 10, "a 7-unit fuel spreads the scene over many steps: {steps}");
    assert_eq!(job.finish().expect("finished"), rasterize(scene(), 32, 24, [1.0, 1.0, 1.0, 1.0]).expect("raster"));
    let unfinished = CpuRasterJob::new(scene(), 32, 24, [0.0; 4]).expect("job");
    assert_eq!(unfinished.finish(), Err(CpuRasterError::Incomplete), "cancelling is not stepping again; nothing half-painted escapes");
}

