fn number(value: &serde_json::Value) -> f64 {
    value.as_f64().expect("fixture number")
}

fn color(value: &serde_json::Value) -> [f32; 4] {
    std::array::from_fn(|channel| number(&value[channel]) as f32 / 255.0)
}

