}

/// ✏️ The fixture path grammar — absolute `M`/`L`/`Q`/`C`/`Z` with whitespace- or comma-separated numbers, a subset of SVG
/// path data both this law and the SVG oracle read verbatim.
fn path(data: &str) -> BezPath {
    let tokens: Vec<String> = data.replace(',', " ").split_whitespace().map(str::to_string).collect();
    let mut path = BezPath::new();
    let mut at = 0;
    let take = |count: usize, at: &mut usize| -> Vec<f64> {
        let values = tokens[*at..*at + count].iter().map(|token| token.parse::<f64>().expect("path number")).collect();
        *at += count;
        values
    };
    while at < tokens.len() {
        let command = tokens[at].clone();
        at += 1;
        match command.as_str() {
            "M" => {
                let v = take(2, &mut at);
                path.move_to((v[0], v[1]));
            }
            "L" => {
                let v = take(2, &mut at);
                path.line_to((v[0], v[1]));
            }
            "Q" => {
                let v = take(4, &mut at);
                path.quad_to(Point::new(v[0], v[1]), Point::new(v[2], v[3]));
            }
            "C" => {
                let v = take(6, &mut at);
                path.curve_to(Point::new(v[0], v[1]), Point::new(v[2], v[3]), Point::new(v[4], v[5]));
            }
            "Z" => path.close_path(),
            other => panic!("fixture path command {other:?} is outside the grammar"),
        }
    }
    path
}

fn face(value: &serde_json::Value) -> semio_framework_fonts::TextFace {
    match value.as_str() {
        Some("mono") => semio_framework_fonts::TextFace::Mono,
        _ => semio_framework_fonts::TextFace::Sans,
    }
}

fn case_scene(case: &serde_json::Value) -> VectorScene {
    let mut scene = VectorScene::new();
    for op in case["ops"].as_array().expect("ops") {
        if let Some(fill) = op.get("fill") {
            let rule = if fill["rule"].as_str() == Some("evenodd") { FillRule::EvenOdd } else { FillRule::NonZero };
            scene.fill_with(path(fill["path"].as_str().expect("d")), transform(&fill["transform"]), Paint::Solid(color(&fill["rgba8"])), rule);
        } else if let Some(stroke) = op.get("stroke") {
            let join = match stroke["join"].as_str() {
                Some("round") => LineJoin::Round,
                Some("bevel") => LineJoin::Bevel,
                _ => LineJoin::Miter,
            };
            let cap = match stroke["cap"].as_str() {
                Some("round") => LineCap::Round,
                Some("square") => LineCap::Square,
                _ => LineCap::Butt,
            };
            let style = StrokeStyle { width: number(&stroke["width"]), join, cap, miter_limit: stroke["miterLimit"].as_f64().unwrap_or(4.0) };
            scene.stroke_with(path(stroke["path"].as_str().expect("d")), transform(&stroke["transform"]), color(&stroke["rgba8"]), style);
        } else if let Some(image) = op.get("image") {
            let pixels: Vec<u8> = image["rgba8"].as_array().expect("texels").iter().map(|value| value.as_u64().expect("texel byte") as u8).collect();
            let raster = RasterImage { width: number(&image["width"]) as u32, height: number(&image["height"]) as u32, pixels };
            scene.image(raster, number(&image["rect"][0]), number(&image["rect"][1]), transform(&image["transform"]), number(&image["opacity"]) as f32);
        } else if let Some(text) = op.get("text") {
            let run = face(&text["face"]).font().expect("embedded face").text_run(text["value"].as_str().expect("text"), number(&text["size"])).expect("run");
            scene.fill(run.outline, Affine::new([1.0, 0.0, 0.0, 1.0, number(&text["x"]), number(&text["y"])]), color(&text["rgba8"]));
        } else {
            panic!("fixture op {op} is outside the schema");
        }
    }
    scene
}

fn case_raster(case: &serde_json::Value) -> RasterImage {
    rasterize(case_scene(case), number(&case["width"]) as u32, number(&case["height"]) as u32, color(&case["background"])).expect("raster")
}

/// 🔏️ LAW (every target): each fixture scene rasterizes to the RGBA8 digest the fixture pins, so the native hosts, the
/// `wasm32-wasip2` guests and the browser renderer paint the same bytes.
#[test]
fn every_fixture_scene_rasterizes_to_its_pinned_digest() {
    let mut mismatches = Vec::new();
    for case in fixture()["cases"].as_array().expect("cases") {
        let digest = semio_framework_hash::sha256_hex(&case_raster(case).pixels);
        if case["expected"]["rgbaSha256"].as_str() != Some(digest.as_str()) {
            mismatches.push(format!("{}: {digest}", case["id"]));
        }
    }
    assert!(mismatches.is_empty(), "digest mismatches: {mismatches:#?}");
}

#[cfg(not(target_family = "wasm"))]
mod oracle {
    use super::*;

    fn css(value: &serde_json::Value) -> String {
        format!("rgb({},{},{})", value[0], value[1], value[2])
    }

    fn opacity(value: &serde_json::Value) -> f64 {
        number(&value[3]) / 255.0
    }

    fn matrix(value: &serde_json::Value) -> String {
        let [a, b, c, d, e, f] = transform(value).as_coeffs();
        format!("matrix({a} {b} {c} {d} {e} {f})")
    }

    fn escape(text: &str) -> String {
        text.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
    }

    fn base64(bytes: &[u8]) -> String {
        const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        bytes
            .chunks(3)
            .flat_map(|chunk| {
                let n = (u32::from(chunk[0]) << 16) | (u32::from(*chunk.get(1).unwrap_or(&0)) << 8) | u32::from(*chunk.get(2).unwrap_or(&0));
                [18, 12, 6, 0].into_iter().enumerate().map(move |(index, shift)| if index <= chunk.len() { ALPHABET[(n >> shift & 0x3f) as usize] as char } else { '=' })
            })
            .collect()
    }

    /// 🔮️ The same case as SVG markup — the input resvg (third-party, test-only) renders as the pixel oracle.
    fn case_svg(case: &serde_json::Value) -> String {
        let (width, height) = (number(&case["width"]), number(&case["height"]));
        let background = &case["background"];
        let mut svg = format!(r#"<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}"><rect width="{width}" height="{height}" fill="{}" fill-opacity="{}"/>"#, css(background), opacity(background));
        for op in case["ops"].as_array().expect("ops") {
            if let Some(fill) = op.get("fill") {
                svg += &format!(r#"<path d="{}" transform="{}" fill="{}" fill-opacity="{}" fill-rule="{}"/>"#, fill["path"].as_str().expect("d"), matrix(&fill["transform"]), css(&fill["rgba8"]), opacity(&fill["rgba8"]), fill["rule"].as_str().unwrap_or("nonzero"));
            } else if let Some(stroke) = op.get("stroke") {
                svg += &format!(
                    r#"<path d="{}" transform="{}" fill="none" stroke="{}" stroke-opacity="{}" stroke-width="{}" stroke-linejoin="{}" stroke-linecap="{}" stroke-miterlimit="{}"/>"#,
                    stroke["path"].as_str().expect("d"),
                    matrix(&stroke["transform"]),
                    css(&stroke["rgba8"]),
                    opacity(&stroke["rgba8"]),
                    number(&stroke["width"]),
                    stroke["join"].as_str().unwrap_or("miter"),
                    stroke["cap"].as_str().unwrap_or("butt"),
                    stroke["miterLimit"].as_f64().unwrap_or(4.0)
                );
            } else if let Some(image) = op.get("image") {
                let pixels: Vec<u8> = image["rgba8"].as_array().expect("texels").iter().map(|value| value.as_u64().expect("byte") as u8).collect();
                let png = semio_framework_pixels::encode_png(&RasterImage { width: number(&image["width"]) as u32, height: number(&image["height"]) as u32, pixels }).expect("png");
                svg += &format!(
                    r#"<image width="{}" height="{}" preserveAspectRatio="none" style="image-rendering:smooth" transform="{}" opacity="{}" href="data:image/png;base64,{}"/>"#,
                    number(&image["rect"][0]),
                    number(&image["rect"][1]),
                    matrix(&image["transform"]),
                    number(&image["opacity"]),
                    base64(&png)
                );
            } else if let Some(text) = op.get("text") {
                let family = if text["face"].as_str() == Some("mono") { "Share Tech Mono" } else { "Anta" };
                svg += &format!(r#"<text x="{}" y="{}" font-family="{family}" font-size="{}" fill="{}" fill-opacity="{}">{}</text>"#, number(&text["x"]), number(&text["y"]), number(&text["size"]), css(&text["rgba8"]), opacity(&text["rgba8"]), escape(text["value"].as_str().expect("text")));
            }
        }
        svg + "</svg>"
    }

    fn oracle_premultiplied(case: &serde_json::Value) -> Vec<f32> {
        let mut options = resvg::usvg::Options::default();
        let mut fonts = resvg::usvg::fontdb::Database::new();
        fonts.load_font_data(semio_framework_fonts::TextFace::Sans.bytes().to_vec());
        fonts.load_font_data(semio_framework_fonts::TextFace::Mono.bytes().to_vec());
        options.fontdb = std::sync::Arc::new(fonts);
        options.font_family = "Anta".into();
        let tree = resvg::usvg::Tree::from_str(&case_svg(case), &options).expect("resvg parses the case svg");
        let mut pixmap = resvg::tiny_skia::Pixmap::new(number(&case["width"]) as u32, number(&case["height"]) as u32).expect("pixmap");
        resvg::render(&tree, resvg::tiny_skia::Transform::identity(), &mut pixmap.as_mut());
        pixmap.data().iter().map(|value| f32::from(*value) / 255.0).collect()
    }

    fn premultiplied(image: &RasterImage) -> Vec<f32> {
        image
            .pixels
            .chunks(4)
            .flat_map(|pixel| {
                let alpha = f32::from(pixel[3]) / 255.0;
                [f32::from(pixel[0]) / 255.0 * alpha, f32::from(pixel[1]) / 255.0 * alpha, f32::from(pixel[2]) / 255.0 * alpha, alpha]
            })
            .collect()
    }

    /// 🔮️ LAW: every fixture scene matches resvg (third-party, test-only) rendering the same scene as SVG within the case's
    /// declared tolerance: the mean premultiplied channel difference and the fraction of channels differing by more than
    /// `farDelta`.
    #[test]
    fn every_fixture_scene_matches_resvg_within_its_tolerance() {
        let mut report = Vec::new();
        for case in fixture()["cases"].as_array().expect("cases") {
            let (ours, theirs) = (premultiplied(&case_raster(case)), oracle_premultiplied(case));
            assert_eq!(ours.len(), theirs.len());
            let tolerance = &case["oracle"];
            let differences: Vec<f32> = ours.iter().zip(&theirs).map(|(a, b)| (a - b).abs()).collect();
            let mean = differences.iter().sum::<f32>() / differences.len() as f32;
            let far = differences.iter().filter(|d| **d > number(&tolerance["farDelta"]) as f32).count() as f32 / differences.len() as f32;
            let painted = theirs.chunks(4).filter(|pixel| pixel[3] > 0.0).count();
            report.push(format!("{} mean {mean:.5} far {far:.5} painted {painted}", case["id"]));
            assert!(mean <= number(&tolerance["meanDelta"]) as f32 && far <= number(&tolerance["farFraction"]) as f32, "{}: mean {mean} far {far} (tolerance {tolerance})\n{}", case["id"], case_svg(case));
        }
        println!("[DEBUG] RS1 resvg oracle: {report:#?}");
    }
}
//#endregion 🔖️Fixtures

