/// 🧢️ How a stroke ends an open subpath (SVG `stroke-linecap`; `butt` is the SVG default).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum LineCap {
    #[default]
    Butt,
    Round,
    Square,
}

/// ✒️ A stroke's geometry in the coordinate space of its path: width, join, cap and the miter limit (SVG default 4).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct StrokeStyle {
    pub width: f64,
    pub join: LineJoin,
    pub cap: LineCap,
    pub miter_limit: f64,
}

impl StrokeStyle {
    /// 🖋️ A stroke of `width` with SVG's defaults: miter joins (limit 4) and butt caps.
    pub fn new(width: f64) -> Self {
        Self { width, join: LineJoin::Miter, cap: LineCap::Butt, miter_limit: 4.0 }
    }
}

