    pub fn image(&mut self, image: RasterImage, width: f64, height: f64, transform: Affine, opacity: f32) {
        if image.width == 0 || image.height == 0 {
            return;
        }
        let mut rectangle = BezPath::new();
        rectangle.move_to((0.0, 0.0));
        rectangle.line_to((width, 0.0));
        rectangle.line_to((width, height));
        rectangle.line_to((0.0, height));
