for op in &scene.ops {
    match op {
        DrawOp::Fill(fill) => {
            let rule = match fill.rule {
                FillRule::NonZero => vello::peniko::Fill::NonZero,
                FillRule::EvenOdd => vello::peniko::Fill::EvenOdd,
            };
            match &fill.paint {
                Paint::Solid(color) => vello_scene.fill(rule, affine_to_vello(fill.transform), vello::peniko::Color::new(*color), None, &path_to_vello(&fill.path)),
                Paint::Image(image) => {
                    let data = vello::peniko::ImageData {
                        data: vello::peniko::Blob::from(image.image.pixels.clone()),
                        format: vello::peniko::ImageFormat::Rgba8,
                        alpha_type: vello::peniko::ImageAlphaType::Alpha,
                        width: image.image.width,
                        height: image.image.height,
                    };
                    let brush = vello::peniko::ImageBrush::new(data).with_alpha(image.opacity);
                    vello_scene.fill(rule, affine_to_vello(fill.transform), &brush, Some(affine_to_vello(image.transform)), &path_to_vello(&fill.path));
                }
            }
        }
        DrawOp::Stroke(stroke) => {
            let join = match stroke.style.join {
                LineJoin::Miter => vello::kurbo::Join::Miter,
                LineJoin::Round => vello::kurbo::Join::Round,
                LineJoin::Bevel => vello::kurbo::Join::Bevel,
            };
            let cap = match stroke.style.cap {
                LineCap::Butt => vello::kurbo::Cap::Butt,
                LineCap::Round => vello::kurbo::Cap::Round,
                LineCap::Square => vello::kurbo::Cap::Square,
            };
            let stroke_style = vello::kurbo::Stroke::new(stroke.style.width).with_join(join).with_caps(cap).with_miter_limit(stroke.style.miter_limit);
            vello_scene.stroke(&stroke_style, affine_to_vello(stroke.transform), vello::peniko::Color::new(stroke.color), None, &path_to_vello(&stroke.path));
        }
    }

