                    }
                    let a2 = a1 + (x1i - x0i - 3) as f32 * inverse_width;
                    self.accumulation[line + x1i - 1] += d * (1.0 - a2 - am);
                }
                self.accumulation[line + x1i] += d * am;
            }
        }
    }

