/// 🌉️ `segments` as a first-party path: arcs become the same cubics every other leaf writes ([`arc_to_cubics`]).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn segments_path(segments: &[PathSegment]) -> BezPath {
    let mut path = BezPath::new();
    let (mut pen, mut start) = ([0.0, 0.0], [0.0, 0.0]);
    let point = |p: [f64; 2]| Point::new(p[0], p[1]);
    for segment in segments {
        match segment {
            PathSegment::MoveTo { to } => {
                pen = [to.x, to.y];
                start = pen;
                path.move_to((to.x, to.y));
            }
            PathSegment::LineTo { to } => {
                pen = [to.x, to.y];
                path.line_to((to.x, to.y));
            }
            PathSegment::QuadTo { c, to } => {
                pen = [to.x, to.y];
                path.quad_to(Point::new(c.x, c.y), point(pen));
            }
            PathSegment::CubicTo { c1, c2, to } => {
                pen = [to.x, to.y];
                path.curve_to(Point::new(c1.x, c1.y), Point::new(c2.x, c2.y), point(pen));
            }
            PathSegment::ArcTo { rx, ry, x_rotation, large_arc, sweep, to } => {
                let cubics = arc_to_cubics(pen, *rx, *ry, *x_rotation, *large_arc, *sweep, [to.x, to.y]);
                if cubics.is_empty() {
                    path.line_to((to.x, to.y));
                }
                for [c1, c2, end] in cubics {
                    path.curve_to(point(c1), point(c2), point(end));
                }
                pen = [to.x, to.y];
            }
            PathSegment::Close => {
                pen = start;
                path.close_path();
            }
        }
    }
    path
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn straight(color: &SemioRgba, opacity: f32) -> [f32; 4] {
    [color.r, color.g, color.b, color.a * opacity]
}

/// 🖌️ Fills and strokes `path` in `node_style` the way SVG paints a `<path>` or `<text>` of that style.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn paint_styled(scene: &mut VectorScene, path: BezPath, transform: SceneAffine, node_style: Option<&str>, styles: &[DrawStyle]) {
    let style = node_style.and_then(|name| styles.iter().find(|s| s.name == name));
    let black = SemioRgba { r: 0.0, g: 0.0, b: 0.0, a: 1.0 };
    let (fill, stroke, width, opacity) = match style {
        Some(s) => (s.fill, s.stroke, s.stroke_width.unwrap_or(1.0), s.opacity.unwrap_or(1.0)),
        None => (Some(black), None, 1.0, 1.0),
    };
    match stroke.filter(|_| width > 0.0) {
        Some(stroke) => {
            if let Some(fill) = fill {
                scene.fill(path.clone(), transform, straight(&fill, opacity));
            }
            scene.stroke(path, transform, straight(&stroke, opacity), width);
        }
        None => {
            if let Some(fill) = fill {
                scene.fill(path, transform, straight(&fill, opacity));
            }
        }
    }
}

// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn paint_node(scene: &mut VectorScene, node: &DrawNode, styles: &[DrawStyle], matrix: &Affine) -> Result<(), String> {
    match node {
        DrawNode::Group { transform, children } => {
            let inner = compose(matrix, &semio_transform_affine(transform));
            for child in children {
                paint_node(scene, child, styles, &inner)?;
            }
        }
        DrawNode::Path { segments, style } => paint_styled(scene, segments_path(segments), SceneAffine::new(*matrix), style.as_deref(), styles),
        DrawNode::Text { value, at, style } => {
            let font = semio_framework_fonts::TextFace::Sans.font().map_err(|error| format!("semio/drawing→png: {error}"))?;
            let run = font.text_run(value, DRAWING_TEXT_SIZE).map_err(|error| format!("semio/drawing→png: {error}"))?;
            paint_styled(scene, run.outline, SceneAffine::new(compose(matrix, &[1.0, 0.0, 0.0, 1.0, at.x, at.y])), style.as_deref(), styles);
        }
        DrawNode::Image { at, width, height, mime, bytes } => {
            if mime != "image/png" || *width <= 0.0 || *height <= 0.0 {
                return Ok(());
            }
            let Ok(source) = semio_s_artifact_stdio_png::io::decode_png(bytes) else { return Ok(()) };
            if source.width == 0 || source.height == 0 {
                return Ok(());
            }
            let image = RasterImage { width: source.width, height: source.height, pixels: source.pixels };
            scene.image(image, *width, *height, SceneAffine::new(compose(matrix, &[1.0, 0.0, 0.0, 1.0, at.x, at.y])), 1.0);
        }
    }
    Ok(())
}

/// 🗺️ `drawing` as the framework's vector scene, with its raster size (see the module doc for the model).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn drawing_vector_scene(drawing: &SemioDrawingSnapshot) -> Result<(VectorScene, u32, u32), String> {
    let (width, height) = (drawing.canvas.width, drawing.canvas.height);
    if !(width.is_finite() && height.is_finite() && width > 0.0 && height > 0.0) {
        return Err("semio/drawing→png: the canvas has no positive finite size".into());
