/// 🔤️ LAW: a `Text` node paints its value in the framework's sans face at SVG's initial size, baseline-anchored at `at` and
/// kerned pairwise — as resvg renders the svg leaf's `<text>` of the same drawing — and an embedded png `Image` is sampled
/// over its box as resvg samples the svg leaf's `<image>`.
#[test]
fn text_and_image_nodes_match_resvg_rendering_the_svg_export() {
    let styles = vec![DrawStyle { name: "ink".into(), fill: rgba(0.1, 0.1, 0.2, 1.0), stroke: None, stroke_width: None, opacity: None }];
    let emblem = semio_s_artifact_stdio_png::io::encode_png(&PngSnapshot {
        schema: semio_s_artifact_stdio_png::STDIO_PNG_DOCUMENT_SCHEMA.into(),
        width: 2,
        height: 2,
        bit_depth: 8,
        color_type: PngColorType::Rgba,
        interlace: false,
        pixels: vec![230, 40, 40, 255, 40, 200, 60, 255, 40, 80, 230, 255, 250, 220, 30, 255],
        chunk_order: vec![PngChunkMarker::Ihdr, PngChunkMarker::Idat, PngChunkMarker::Iend],
        ..PngSnapshot::default()
    })
    .expect("emblem png");
    let drawing = drawing(
        200.0,
        96.0,
        styles,
        vec![
            DrawNode::Image { at: p(120.0, 8.0), width: 64.0, height: 64.0, mime: "image/png".into(), bytes: emblem },
            DrawNode::Text { value: "Semio AV Wa 42".into(), at: p(8.0, 40.0), style: Some("ink".into()) },
            DrawNode::Text { value: "Größe · Tour".into(), at: p(8.0, 80.0), style: None },
        ],
    );
    let ours = rasterize_drawing(&drawing).expect("raster");
    let oracle = resvg_premultiplied(&drawing, ours.width, ours.height);
    let mine = premultiplied(&ours.rgba8);
    let differences: Vec<f32> = mine.iter().zip(&oracle).map(|(a, b)| (a - b).abs()).collect();
    let mean = differences.iter().sum::<f32>() / differences.len() as f32;
    let far = differences.iter().filter(|d| **d > 0.25).count() as f32 / differences.len() as f32;
    let inked = oracle.chunks(4).filter(|px| px[3] > 0.5).count();
    assert!(inked > 1500, "the oracle painted {inked} pixels");
    assert!(mean < 0.02 && far < 0.03, "text/image: mean premultiplied channel difference {mean}, far fraction {far}");
}

