/// 🖼️ A smooth 32×32 emblem (a radial gradient with a translucent rim) as PNG bytes.
#[cfg(not(target_family = "wasm"))]
fn gradient_emblem_png() -> Vec<u8> {
    let mut pixels = Vec::with_capacity(32 * 32 * 4);
    for y in 0..32u32 {
        for x in 0..32u32 {
            let d = (((x as f32 - 15.5).powi(2) + (y as f32 - 15.5).powi(2)).sqrt() / 16.0).min(1.0);
            pixels.extend_from_slice(&[(40.0 + 200.0 * (1.0 - d)) as u8, (60.0 + 120.0 * d) as u8, 200, (255.0 * (1.0 - 0.6 * d)) as u8]);
        }
    }
    semio_s_artifact_stdio_png::io::encode_png(&semio_s_artifact_stdio_png::PngSnapshot {
        schema: semio_s_artifact_stdio_png::STDIO_PNG_DOCUMENT_SCHEMA.into(),
        width: 32,
        height: 32,
        bit_depth: 8,
        color_type: semio_s_artifact_stdio_png::schema::snapshot::PngColorType::Rgba,
        interlace: false,
        pixels,
        chunk_order: vec![semio_s_artifact_stdio_png::schema::snapshot::PngChunkMarker::Ihdr, semio_s_artifact_stdio_png::schema::snapshot::PngChunkMarker::Idat, semio_s_artifact_stdio_png::schema::snapshot::PngChunkMarker::Iend],
        ..semio_s_artifact_stdio_png::PngSnapshot::default()
    })
    .expect("emblem png")
}

/// 📷️ LAW: `photos:out`'s PNG (the framework's CPU raster tier, the same bytes on every tier) matches resvg rendering the
/// shot's svg export — frame, label and emblem — within the tolerance of the stdio drawing leaf's own oracle law, for the
/// default transparent rectangle, an opaque ellipse, and a shot with an emblem.
#[cfg(not(target_family = "wasm"))]
#[semio_framework_async_macros::async_test]
async fn the_photo_png_matches_resvg_rendering_the_shot_svg() {
    let default = default_snapshot();
    let mut ellipse = default_snapshot();
    let active = ellipse.active_shot_id.clone();
    for shot in ellipse.shots.iter_mut().filter(|shot| shot.id == active || active.is_empty()) {
        shot.shape = "ellipse".into();
        shot.background = Some("#1e293b".into());
    }
    let mut emblem = default_snapshot();
    crate::shooting_set_emblem_from_base64(&mut emblem, Some(&crate::shooting_base64_encode(&gradient_emblem_png())));
    for (name, snapshot) in [("default", default), ("ellipse", ellipse), ("emblem", emblem)] {
        let png = shooting_scene_png(&snapshot).expect("photo png");
        let decoded = semio_s_artifact_stdio_png::io::decode_png(&png).expect("the photo decodes as png");
        let (width, height, oracle) = resvg_premultiplied(&snapshot);
        assert_eq!((decoded.width, decoded.height), (width, height), "{name}: the photo is the shot's size");
        let ours: Vec<f32> = decoded.pixels.chunks(4).flat_map(|px| {
            let alpha = f32::from(px[3]) / 255.0;
            [f32::from(px[0]) / 255.0 * alpha, f32::from(px[1]) / 255.0 * alpha, f32::from(px[2]) / 255.0 * alpha, alpha]
        }).collect();
        let differences: Vec<f32> = ours.iter().zip(&oracle).map(|(a, b)| (a - b).abs()).collect();
        let mean = differences.iter().sum::<f32>() / differences.len() as f32;
        let far = differences.iter().filter(|d| **d > 0.25).count() as f32 / differences.len() as f32;
        let painted = oracle.chunks(4).filter(|px| px[3] > 0.0).count();
        assert!(painted > 1000, "{name}: the oracle painted {painted} pixels");
        assert!(mean < 0.006 && far < 0.004, "{name}: mean premultiplied channel difference {mean}, far fraction {far}");
    }
}

